import { memo } from 'react';
import { motion } from 'framer-motion';
import { Card, CardContent } from '@/components/ui/card';
import type { IAbilityIndicator } from '@/types/attention';
import { MOCK_ABILITY_INDICATORS } from '@/data/attention';

// 将 Tailwind text-chart-* 类名映射为 SVG stroke 可用的 HSL 颜色值
const COLOR_MAP: Record<string, string> = {
  'text-chart-1': 'hsl(142 65% 45%)',
  'text-chart-2': 'hsl(28 90% 55%)',
  'text-chart-3': 'hsl(202 65% 45%)',
  'text-chart-4': 'hsl(52 65% 45%)',
};

interface DashboardSectionProps {
  indicators?: IAbilityIndicator[];
}

// ============================================================
// 环形进度组件
// ============================================================
function CircularProgress({
  score,
  maxScore,
  color,
  size = 96,
  strokeWidth = 8,
}: {
  score: number;
  maxScore: number;
  color: string;
  size?: number;
  strokeWidth?: number;
}) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const progress = Math.min(score / maxScore, 1);
  const offset = circumference * (1 - progress);

  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <svg
        width={size}
        height={size}
        className="-rotate-90"
        aria-label={`${score} / ${maxScore}`}
      >
        {/* 背景轨道 */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="hsl(100 35% 85%)"
          strokeWidth={strokeWidth}
        />
        {/* 进度弧（入场动画） */}
        <motion.circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={circumference}
          initial={{ strokeDashoffset: circumference }}
          whileInView={{ strokeDashoffset: offset }}
          viewport={{ once: true }}
          transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1], delay: 0.2 }}
        />
      </svg>
      {/* 中心分数 */}
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span className="text-2xl md:text-3xl font-bold tabular-nums text-foreground">
          {score}
        </span>
        <span className="text-[10px] text-muted-foreground leading-none">分</span>
      </div>
    </div>
  );
}

// ============================================================
// 综合能力仪表盘 Section
// ============================================================
function DashboardSection({ indicators = MOCK_ABILITY_INDICATORS }: DashboardSectionProps) {
  return (
    <section className="w-full py-8">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-5">
          {indicators.map((indicator, i) => (
            <motion.div
              key={indicator.id}
              initial={{ opacity: 0, y: 24 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: i * 0.1, ease: [0.16, 1, 0.3, 1] }}
              whileHover={{ y: -4, transition: { duration: 0.2 } }}
            >
              <Card className="rounded-2xl border-border/40 shadow-sm h-full">
                <CardContent className="flex flex-col items-center gap-3 p-5">
                  <CircularProgress
                    score={indicator.score}
                    maxScore={indicator.maxScore}
                    color={COLOR_MAP[indicator.colorClass] || COLOR_MAP['text-chart-1']}
                  />
                  <div className="text-center">
                    <p className="text-sm font-semibold text-foreground leading-tight">
                      {indicator.name}
                    </p>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default memo(DashboardSection);
