// 游戏4：反应力测试
// ============================================================
const STIMULI_COUNT = 20;
const STIMULUS_TYPES = [
  { icon: '🌟', isTarget: true, label: 'star' },
  { icon: '💣', isTarget: false, label: 'bomb' },
  { icon: '🌸', isTarget: false, label: 'flower' },
  { icon: '⚽', isTarget: false, label: 'ball' },
  { icon: '🎵', isTarget: false, label: 'music' },
  { icon: '📱', isTarget: false, label: 'phone' },
];

function ReactionGame({ onComplete, onScore }: { onComplete: () => void; onScore: (s: number) => void }) {
  const [started, setStarted] = useState(false);
  const [stimulusIndex, setStimulusIndex] = useState(0);
  const [currentStimulus, setCurrentStimulus] = useState<(typeof STIMULUS_TYPES)[number] | null>(null);
  const [phase, setPhase] = useState<'waiting' | 'showing' | 'feedback'>('waiting');
  const [correctCount, setCorrectCount] = useState(0);
  const [wrongCount, setWrongCount] = useState(0);
  const [missCount, setMissCount] = useState(0);
  const [feedbackText, setFeedbackText] = useState('');
  const [finished, setFinished] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const stimuli = useMemo(() => {
    const arr: (typeof STIMULUS_TYPES)[number][] = [];
    for (let i = 0; i < STIMULI_COUNT; i++) {
      arr.push(STIMULUS_TYPES[Math.floor(Math.random() * STIMULUS_TYPES.length)]);
    }
    return arr;
  }, []);

  function showNextStimulus() {
    if (stimulusIndex >= STIMULI_COUNT) {
      setFinished(true);
      const total = correctCount + wrongCount + missCount;
      const score = total > 0 ? Math.round((correctCount / total) * 100) : 0;
      onScore(score);
      return;
    }
    const stim = stimuli[stimulusIndex];
    setCurrentStimulus(stim);
    setPhase('showing');

    timeoutRef.current = setTimeout(() => {
      setPhase('waiting');
      setMissCount((m) => m + 1);
      setFeedbackText('太慢了~');
      setTimeout(() => {
        setStimulusIndex((i) => i + 1);
        setFeedbackText('');
      }, 600);
    }, 1500);
  }

  useEffect(() => {
    if (started && phase === 'waiting' && !finished) {
      const t = setTimeout(showNextStimulus, 600 + Math.random() * 800);
      return () => clearTimeout(t);
    }
  }, [started, phase, stimulusIndex, finished]);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  function handleClick() {
    if (phase !== 'showing' || !currentStimulus) return;
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    if (currentStimulus.isTarget) {
      setCorrectCount((c) => c + 1);
      setFeedbackText('好快的反应！⚡');
    } else {
      setWrongCount((w) => w + 1);
      setFeedbackText('小心，要看清楚~');
    }
    setPhase('feedback');
    setTimeout(() => {
      setStimulusIndex((i) => i + 1);
      setPhase('waiting');
      setFeedbackText('');
    }, 700);
  }

  function handleDone() {
    onComplete();
  }

  if (!started) {
    return (
      <div className="space-y-6">
        <GameProgress current={4} total={4} label="第4/4项" />
        <div className="flex flex-col items-center gap-6 py-8">
          <div className="text-5xl">🌟💣</div>
          <p className="text-sm text-muted-foreground text-center max-w-sm">
            看到星星就快点它！<br />看到炸弹千万别点哦~
          </p>
          <ElephantBubble message="看到星星就快点它！看到炸弹千万别点哦~" emoji="✋" />
          <Button onClick={() => setStarted(true)} size="lg" className="rounded-full gap-2">
            <Play className="size-4 fill-current" />
            开始测试
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <GameProgress current={4} total={4} label="第4/4项" />

      {/* 统计 */}
      <div className="flex items-center justify-center gap-6 text-sm">
        <span className="text-emerald-600 font-semibold">✅ {correctCount}</span>
        <span className="text-red-500 font-semibold">❌ {wrongCount}</span>
        <span className="text-muted-foreground">进度 {stimulusIndex}/{STIMULI_COUNT}</span>
      </div>

      {/* 刺激区域 */}
      <div className="flex justify-center py-8">
        <button
          type="button"
          onClick={handleClick}
          disabled={phase !== 'showing' || finished}
          className={`size-32 md:size-40 rounded-full border-4 flex items-center justify-center transition-all duration-300 ${
            phase === 'showing'
              ? 'border-primary/30 bg-white shadow-lg shadow-primary/10 cursor-pointer hover:scale-105 hover:shadow-xl'
              : 'border-border/20 bg-muted/30 cursor-default'
          }`}
        >
          {phase === 'showing' && currentStimulus && (
            <motion.span
              key={stimulusIndex}
              initial={{ scale: 0, rotate: -30 }}
              animate={{ scale: 1, rotate: 0 }}
              transition={{ type: 'spring', stiffness: 300, damping: 15 }}
              className="text-5xl md:text-6xl"
            >
              {currentStimulus.icon}
            </motion.span>
          )}
          {phase === 'waiting' && (
            <span className="text-3xl text-muted-foreground/30">?</span>
          )}
          {phase === 'feedback' && (
            <span className="text-3xl text-muted-foreground/30">—</span>
          )}
        </button>
      </div>

      {/* 反馈 */}
      {feedbackText && (
        <motion.p
          key={feedbackText}
          initial={{ opacity: 0, y: -8 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center text-sm font-semibold text-foreground"
        >
          {feedbackText}
        </motion.p>
      )}

      {/* 小象提示 */}
      <ElephantBubble
        message={
          finished
            ? `全部完成啦！你真棒！🏆 正确${correctCount}次`
            : '看到星星就快点它！看到炸弹千万别点哦~'
        }
        emoji={finished ? '🏆' : '✋'}
      />

      {finished && (
        <div className="flex justify-end">
          <Button onClick={handleDone} className="rounded-full gap-1.5" size="sm">
            查看报告
            <ArrowRight className="size-3.5" />
          </Button>
        </div>
      )}
    </div>
  );
}

