import { motion } from 'framer-motion';
import { Crown, Medal, Star } from 'lucide-react';
import type { IRankingStudent } from '@/types/attention';

interface PodiumSectionProps {
  students: IRankingStudent[];
}

const PODIUM_CONFIG = [
  { height: 'h-28 md:h-36', color: 'bg-chart-3', labelColor: 'text-chart-3', rankLabel: '🥈 第2名' },
  { height: 'h-36 md:h-48', color: 'bg-chart-2', labelColor: 'text-chart-2', rankLabel: '👑 第1名' },
  { height: 'h-24 md:h-28', color: 'bg-chart-4', labelColor: 'text-chart-4', rankLabel: '🥉 第3名' },
] as const;

const MEDAL_ICONS = [Medal, Crown, Star] as const;

export default function PodiumSection({ students }: PodiumSectionProps) {
  const top3 = students.slice(0, 3);
  // Reorder for podium layout: [2nd, 1st, 3rd]
  const podiumOrder = [top3[1], top3[0], top3[2]];
  const rest = students.slice(3);

  return (
    <div className="space-y-14">
      {/* ================================================================ */}
      {/* 前三名领奖台 */}
      {/* ================================================================ */}
      <div className="flex items-end justify-center gap-3 md:gap-6 px-2">
        {podiumOrder.map((student, i) => {
          if (!student) return null;
          const config = PODIUM_CONFIG[i];
          const MedalIcon = MEDAL_ICONS[i];

          return (
            <motion.div
              key={student.id}
              initial={{ opacity: 0, y: 60 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.7, delay: i * 0.18, ease: [0.16, 1, 0.3, 1] }}
              className="flex flex-col items-center gap-2.5"
            >
              {/* 头像 + 奖牌 */}
              <div className="relative">
                <div
                  className="size-16 md:size-20 rounded-full flex items-center justify-center text-xl md:text-2xl font-black text-white shadow-lg border-[3px] border-white/90"
                  style={{ backgroundColor: student.avatarColor }}
                >
                  {student.name[0]}
                </div>
                <MedalIcon
                  className={`absolute -top-2.5 -right-2.5 size-6 md:size-7 ${config.labelColor} drop-shadow-md`}
                />
              </div>

              {/* 姓名 */}
              <span className="font-bold text-foreground text-sm md:text-base">
                {student.name}
              </span>

              {/* 成就标签 */}
              <span className="text-[11px] md:text-xs text-muted-foreground bg-muted/60 px-2.5 py-0.5 rounded-full">
                {student.achievement}
              </span>

              {/* 积分 */}
              <span className="text-sm md:text-base font-extrabold text-primary tabular-nums">
                {student.score.toLocaleString()}
                <span className="text-[10px] md:text-xs font-normal text-muted-foreground ml-0.5">分</span>
              </span>

              {/* 领奖台底座 */}
              <div
                className={`${config.height} w-24 md:w-32 ${config.color} rounded-t-2xl flex items-start justify-center pt-3 shadow-lg relative overflow-hidden`}
              >
                {/* 底座高光 */}
                <div className="absolute inset-x-0 top-0 h-1/3 bg-white/15 rounded-t-2xl" />
                <span className="relative text-white font-black text-xl md:text-2xl drop-shadow-md">
                  {student.rank}
                </span>
              </div>

              {/* 排名标签 */}
              <span className="text-[11px] md:text-xs font-semibold text-muted-foreground">
                {config.rankLabel}
              </span>
            </motion.div>
          );
        })}
      </div>

      {/* ================================================================ */}
      {/* 第4-8名网格 */}
      {/* ================================================================ */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 md:gap-4">
        {rest.map((student, i) => (
          <motion.div
            key={student.id}
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: 0.4 + i * 0.07, ease: [0.16, 1, 0.3, 1] }}
            whileHover={{ y: -4, transition: { duration: 0.2 } }}
            className="flex flex-col items-center gap-2 p-4 rounded-2xl bg-card border border-border/30 shadow-sm hover:shadow-md transition-shadow cursor-default"
          >
            {/* 头像 */}
            <div
              className="size-12 md:size-14 rounded-full flex items-center justify-center text-base md:text-lg font-bold text-white shadow-sm"
              style={{ backgroundColor: student.avatarColor }}
            >
              {student.name[0]}
            </div>

            {/* 姓名 */}
            <span className="font-semibold text-foreground text-sm truncate max-w-full">
              {student.name}
            </span>

            {/* 排名 */}
            <span className="text-[11px] text-muted-foreground">
              第 {student.rank} 名
            </span>

            {/* 积分 */}
            <span className="text-xs font-bold text-primary tabular-nums">
              {student.score.toLocaleString()}
              <span className="font-normal text-muted-foreground ml-0.5">分</span>
            </span>
          </motion.div>
        ))}
      </div>
    </div>
  );
}
