import { useState } from 'react';
import { NavLink } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';

export default function Header() {
  const [loginOpen, setLoginOpen] = useState(false);
  const [aiTestOpen, setAiTestOpen] = useState(false);
  const [phone, setPhone] = useState('');
  const [childName, setChildName] = useState('');

  function handleLoginSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!phone.trim()) {
      toast.error('请输入手机号');
      return;
    }
    toast.success('登录成功！欢迎回来');
    setLoginOpen(false);
    setPhone('');
  }

  function handleAiTestSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!childName.trim()) {
      toast.error('请输入孩子姓名');
      return;
    }
    toast.success('AI测评申请已提交，我们将尽快联系您！');
    setAiTestOpen(false);
    setChildName('');
  }

  return (
    <>
      <header className="sticky top-0 z-50 w-full bg-background/80 backdrop-blur-md border-b border-border/30">
        <div className="max-w-7xl mx-auto px-4 md:px-6 flex h-16 items-center justify-between">
          {/* 左侧：系统标题 */}
          <NavLink to="/" end className="flex items-center gap-1.5 shrink-0 min-w-0">
            <span className="text-xl md:text-2xl font-extrabold tracking-tight text-primary">
              Elefoc
            </span>
            <span className="text-sm md:text-base font-semibold text-foreground/80 truncate">
              专注象：注意力Ai评测与训练具身智能机器人
            </span>
          </NavLink>

          {/* 右侧：操作按钮 */}
          <div className="flex items-center gap-3 shrink-0">
            <Button
              variant="default"
              size="sm"
              className="bg-accent hover:bg-accent/90 text-accent-foreground font-semibold rounded-full px-5"
              onClick={() => setAiTestOpen(true)}
            >
              立即免费AI测评
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="rounded-full px-5"
              onClick={() => setLoginOpen(true)}
            >
              登录
            </Button>
          </div>
        </div>
      </header>

      {/* 登录弹窗 */}
      <Dialog open={loginOpen} onOpenChange={setLoginOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>家长登录</DialogTitle>
            <DialogDescription>
              请输入手机号快速登录，查看孩子的训练数据
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleLoginSubmit}>
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label htmlFor="phone">手机号</Label>
                <Input
                  id="phone"
                  type="tel"
                  placeholder="请输入手机号"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                />
              </div>
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setLoginOpen(false)}>
                取消
              </Button>
              <Button type="submit">登录</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* AI测评弹窗 */}
      <Dialog open={aiTestOpen} onOpenChange={setAiTestOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>免费AI注意力测评</DialogTitle>
            <DialogDescription>
              填写孩子基本信息，即可免费获得一次AI注意力测评机会
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleAiTestSubmit}>
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label htmlFor="childName">孩子姓名</Label>
                <Input
                  id="childName"
                  placeholder="请输入孩子姓名"
                  value={childName}
                  onChange={(e) => setChildName(e.target.value)}
                />
              </div>
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setAiTestOpen(false)}>
                取消
              </Button>
              <Button type="submit">提交申请</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}
