// ============================================================
// 记忆灯游戏常量
// ============================================================
const MEMORY_GAME_STORAGE_KEY = '__app_focus_memory_game_score';
const COLORS = ['#FF6B6B', '#4ECDC4', '#FFE66D', '#A78BFA', '#FB923C', '#38BDF8'];
const MAX_ROUND = 8;

// ============================================================
// 记忆灯游戏组件
// ============================================================
function MemoryLampGame({ onClose }: { onClose: () => void }) {
  const [sequence, setSequence] = useState<number[]>([]);
  const [userInput, setUserInput] = useState<number[]>([]);
  const [phase, setPhase] = useState<'showing' | 'input' | 'result'>('showing');
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [bestScore, setBestScore] = useState(() => {
    try {
      const stored = scopedStorage.getItem(MEMORY_GAME_STORAGE_KEY);
      return stored ? Number(stored) : 0;
    } catch {
      return 0;
    }
  });

  // 生成新序列
  const generateSequence = useCallback(() => {
    const newSeq: number[] = [];
    for (let i = 0; i < round + 2; i++) {
      newSeq.push(Math.floor(Math.random() * COLORS.length));
    }
    return newSeq;
  }, [round]);

  // 开始展示序列
  const startShowing = useCallback(() => {
    const newSeq = generateSequence();
    setSequence(newSeq);
    setUserInput([]);
    setPhase('showing');
    setActiveIndex(null);

    let i = 0;
    const interval = setInterval(() => {
      if (i < newSeq.length) {
        setActiveIndex(newSeq[i]);
        setTimeout(() => setActiveIndex(null), 400);
        i++;
      } else {
        clearInterval(interval);
        setPhase('input');
      }
    }, 800);
  }, [generateSequence]);

  useEffect(() => {
    startShowing();
  }, [startShowing]);

  // 用户点击颜色
  function handleColorClick(index: number) {
    if (phase !== 'input') return;

    const newInput = [...userInput, index];
    setUserInput(newInput);

    // 检查当前输入是否正确
    const currentPos = newInput.length - 1;
    if (newInput[currentPos] !== sequence[currentPos]) {
      // 错误
      setPhase('result');
      const finalScore = score;
      if (finalScore > bestScore) {
        setBestScore(finalScore);
        try {
          scopedStorage.setItem(MEMORY_GAME_STORAGE_KEY, String(finalScore));
        } catch (e) {
          logger.error('Failed to save score:', String(e));
        }
        toast.success(`新纪录！最高分：${finalScore}`);
      } else {
        toast.info(`本轮得分：${finalScore}`);
      }
      return;
    }

    // 全部正确
    if (newInput.length === sequence.length) {
      const newScore = score + round * 10;
      setScore(newScore);
      if (round < MAX_ROUND) {
        setRound((r) => r + 1);
        // 短暂延迟后进入下一轮
        setTimeout(() => {
          const nextSeq = generateSequence();
          setSequence(nextSeq);
          setUserInput([]);
          setPhase('showing');
          setActiveIndex(null);

          let i = 0;
          const interval = setInterval(() => {
            if (i < nextSeq.length) {
              setActiveIndex(nextSeq[i]);
              setTimeout(() => setActiveIndex(null), 400);
              i++;
            } else {
              clearInterval(interval);
              setPhase('input');
            }
          }, 800);
        }, 600);
      } else {
        // 通关
        setPhase('result');
        const finalScore = score + MAX_ROUND * 10;
        setScore(finalScore);
        if (finalScore > bestScore) {
          setBestScore(finalScore);
          try {
            scopedStorage.setItem(MEMORY_GAME_STORAGE_KEY, String(finalScore));
          } catch (e) {
            logger.error('Failed to save score:', String(e));
          }
        }
        toast.success('🎉 恭喜通关！全部关卡完成！');
      }
    }
  }

  // 重新开始
  function handleRestart() {
    setRound(1);
    setScore(0);
    setSequence([]);
    setUserInput([]);
    setPhase('showing');
    setActiveIndex(null);
    setTimeout(() => {
      const newSeq: number[] = [];
      for (let i = 0; i < 3; i++) {
        newSeq.push(Math.floor(Math.random() * COLORS.length));
      }
      setSequence(newSeq);
      setUserInput([]);
      setPhase('showing');
      setActiveIndex(null);

      let i = 0;
      const interval = setInterval(() => {
        if (i < newSeq.length) {
          setActiveIndex(newSeq[i]);
          setTimeout(() => setActiveIndex(null), 400);
          i++;
        } else {
          clearInterval(interval);
          setPhase('input');
        }
      }, 800);
    }, 100);
  }

  return (
    <div className="flex flex-col items-center gap-6 py-4">
      {/* 游戏信息 */}
      <div className="flex items-center gap-6 text-sm">
        <span className="text-muted-foreground">
          第 <span className="font-bold text-foreground">{round}</span> / {MAX_ROUND} 关
        </span>
        <span className="text-muted-foreground">
          得分：<span className="font-bold text-accent">{score}</span>
        </span>
        <span className="text-muted-foreground">
          最高分：<span className="font-bold text-primary">{bestScore}</span>
        </span>
      </div>

      {/* 颜色灯阵 */}
      <div className="grid grid-cols-3 gap-4">
        {COLORS.map((color, index) => (
          <button
            key={index}
            type="button"
            disabled={phase !== 'input'}
            onClick={() => handleColorClick(index)}
            className={`size-20 rounded-2xl border-4 transition-all duration-200 ${
              activeIndex === index
                ? 'scale-110 brightness-150 border-white shadow-lg shadow-white/40'
                : 'border-transparent hover:scale-105'
            } ${phase !== 'input' ? 'cursor-default' : 'cursor-pointer hover:shadow-md'}`}
            style={{ backgroundColor: color }}
            aria-label={`颜色按钮 ${index + 1}`}
          />
        ))}
      </div>

      {/* 状态提示 */}
      <div className="text-center">
        {phase === 'showing' && (
          <p className="text-sm text-muted-foreground animate-pulse">👀 记住灯亮的顺序...</p>
        )}
        {phase === 'input' && (
          <p className="text-sm text-primary font-semibold">
            👆 按顺序点击颜色按钮（{userInput.length}/{sequence.length}）
          </p>
        )}
        {phase === 'result' && (
          <div className="flex flex-col items-center gap-3">
            <p className="text-lg font-bold text-accent">
              {round > MAX_ROUND ? '🎉 全部通关！' : '游戏结束'}
            </p>
            <Button size="sm" variant="outline" onClick={handleRestart}>
              <RotateCcw className="size-4" />
              再来一次
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

// ============================================================
// 训练项目卡片
// ============================================================
function ProjectCard({ project, onPlay, onDetail }: { project: ITrainProject; onPlay: (project: ITrainProject) => void; onDetail: (project: ITrainProject) => void }) {
  const detail = GAME_DETAILS[project.id];
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
      whileHover={{ y: -6, scale: 1.03, transition: { duration: 0.25 } }}
      className="group cursor-pointer"
    >
      <Card className="overflow-hidden border-border/40 shadow-sm hover:shadow-lg transition-all duration-300 h-full">
        {/* 图片区域 */}
        <div className="relative aspect-[4/3] bg-gradient-to-br from-muted/50 to-muted overflow-hidden">
          <Image
            src={project.imageUrl}
            alt={project.name}
            className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-400"
          />
          {/* 悬浮操作层 */}
          <div className="absolute inset-0 flex items-center justify-center gap-2 bg-black/0 group-hover:bg-black/25 transition-all duration-300">
            <Button
              size="icon"
              variant="secondary"
              className="opacity-0 group-hover:opacity-100 translate-y-2 group-hover:translate-y-0 transition-all duration-300 rounded-full size-10 shadow-lg"
              onClick={(e) => {
                e.stopPropagation();
                onPlay(project);
              }}
              aria-label={`开始 ${project.name}`}
            >
              <Play className="size-5 fill-current" />
            </Button>
            {detail && (
              <Button
                size="icon"
                variant="secondary"
                className="opacity-0 group-hover:opacity-100 translate-y-2 group-hover:translate-y-0 transition-all duration-300 delay-75 rounded-full size-10 shadow-lg"
                onClick={(e) => {
                  e.stopPropagation();
                  onDetail(project);
                }}
                aria-label={`查看 ${project.name} 详情`}
              >
                <Info className="size-5" />
              </Button>
            )}
          </div>
        </div>
        {/* 文字区域 */}
        <CardContent className="p-2.5 text-center">
          <p className="text-xs font-semibold text-foreground truncate">{project.name}</p>
          <p className="text-[10px] text-muted-foreground mt-0.5 line-clamp-1">{project.description}</p>
        </CardContent>
      </Card>
    </motion.div>
  );
}

// ============================================================
// 主组件
// ============================================================
export default function TrainTabsSection() {
  const [gameOpen, setGameOpen] = useState(false);
  const [detailOpen, setDetailOpen] = useState(false);
  const [selectedProject, setSelectedProject] = useState<ITrainProject | null>(null);

  // 只保留4个指定训练项目
  const projects = useMemo(
    () => MOCK_TRAIN_PROJECTS.filter((p) => ['tp-3', 'tp-13', 'tp-16', 'tp-17'].includes(p.id)),
    [],
  );

  function handlePlay(project: ITrainProject) {
    setSelectedProject(project);
    if (project.id === 'tp-1') {
      setGameOpen(true);
    } else {
      toast.info(`${project.name}即将开放，敬请期待！`);
    }
  }

  function handleDetail(project: ITrainProject) {
    setSelectedProject(project);
    setDetailOpen(true);
  }

  function handleCloseGame() {
    setGameOpen(false);
    setSelectedProject(null);
  }

  function handleCloseDetail() {
    setDetailOpen(false);
    setSelectedProject(null);
  }

  return (
    <section className="w-full py-4 md:py-6">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
          {projects.map((project) => (
            <ProjectCard key={project.id} project={project} onPlay={handlePlay} onDetail={handleDetail} />
          ))}
        </div>
      </div>

      {/* 记忆灯游戏弹窗 */}
      <Dialog open={gameOpen} onOpenChange={(open) => { if (!open) handleCloseGame(); }}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-xl">
              💡 {selectedProject?.name ?? '记忆灯'}
            </DialogTitle>
          </DialogHeader>
          <MemoryLampGame onClose={handleCloseGame} />
        </DialogContent>
      </Dialog>

      {/* 游戏详情弹窗 */}
      <Dialog open={detailOpen} onOpenChange={(open) => { if (!open) handleCloseDetail(); }}>
        <DialogContent className="sm:max-w-md">
          {selectedProject && GAME_DETAILS[selectedProject.id] && (
            <>
              <DialogHeader>
                <DialogTitle className="text-xl">{selectedProject.name}</DialogTitle>
                <DialogDescription>{selectedProject.description}</DialogDescription>
              </DialogHeader>
              <div className="space-y-4 py-2">
                <div className="flex items-start gap-3 p-3 rounded-xl bg-amber-50">
                  <Info className="size-5 text-amber-500 mt-0.5 shrink-0" />
                  <div>
                    <p className="text-sm font-semibold text-amber-800 mb-1">玩法介绍</p>
                    <p className="text-sm text-amber-700 leading-relaxed">{GAME_DETAILS[selectedProject.id].howToPlay}</p>
                  </div>
                </div>
                <div className="flex items-start gap-3 p-3 rounded-xl bg-blue-50">
                  <User className="size-5 text-blue-500 mt-0.5 shrink-0" />
                  <div>
                    <p className="text-sm font-semibold text-blue-800 mb-1">适合年龄</p>
                    <p className="text-sm text-blue-700">{GAME_DETAILS[selectedProject.id].ageRange}</p>
                  </div>
                </div>
                <div className="flex items-start gap-3 p-3 rounded-xl bg-emerald-50">
                  <Target className="size-5 text-emerald-500 mt-0.5 shrink-0" />
                  <div>
                    <p className="text-sm font-semibold text-emerald-800 mb-1">训练目标</p>
                    <p className="text-sm text-emerald-700 leading-relaxed">{GAME_DETAILS[selectedProject.id].goal}</p>
                  </div>
                </div>
              </div>
              <div className="flex justify-end gap-2 pt-2">
                <Button variant="outline" onClick={handleCloseDetail}>关闭</Button>
                <Button onClick={() => { handleCloseDetail(); handlePlay(selectedProject); }}>
                  <Play className="size-4 mr-1" />
                  开始训练
                </Button>
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </section>
  );
}
