import { useState, useRef, useEffect, type FormEvent } from 'react';
import { motion } from 'framer-motion';
import { Send, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Image } from '@/components/ui/image';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { IMAGE_PATHS, QUICK_QUESTIONS, MOCK_CHAT_MESSAGES } from '@/data/attention';
import type { IChatMessage } from '@/types/attention';

// AI预设回复库
const AI_REPLIES: Record<string, string> = {
  '什么是注意力缺陷？':
    '注意力缺陷是一种常见的儿童神经发育障碍，主要表现为注意力不集中、容易分心、做事拖拉等。但别担心，通过科学的训练和干预，大多数孩子都能得到明显改善！建议先完成我们的注意力测评，了解孩子的具体情况 🧠',
  '如何在家训练？':
    '在家训练可以从简单的游戏开始哦～比如"记忆灯"游戏（记住灯光顺序）、"舒尔特方格"（按顺序找数字）、"杯下寻物"（追踪杯子移动）。每天坚持10-15分钟，效果会很明显！我们的"趣味互动"模块有17个训练项目可以试试 🎮',
  '孩子坐不住怎么办？':
    '孩子坐不住是很常见的现象～可以试试：1️⃣ 把任务拆分成小块，每次只做3-5分钟；2️⃣ 使用计时器，让孩子看到"还剩多久"；3️⃣ 完成任务后立即给予奖励；4️⃣ 允许孩子在座位上小幅活动。我们的AI训练方案会根据孩子的表现自动调整难度哦 💪',
  '训练多久有效？':
    '根据我们的数据，坚持训练8周后，孩子的持续性注意力平均提升23分！当然每个孩子情况不同，一般建议：初级阶梯每天5分钟，中级阶梯每天10分钟，高级阶梯每天15分钟。关键是坚持和趣味性，让孩子觉得训练像玩游戏一样开心 🌟',
};

// 语音波动动画条
function VoiceWaveBars() {
  return (
    <div className="flex items-center gap-1 h-8">
      {[0, 1, 2, 3, 4].map((i) => (
        <motion.div
          key={i}
          className="w-1 rounded-full bg-primary/60"
          animate={{
            height: [8, 24, 12, 28, 16][i],
          }}
          transition={{
            duration: 0.6 + i * 0.12,
            repeat: Infinity,
            repeatType: 'reverse',
            ease: 'easeInOut',
            delay: i * 0.1,
          }}
        />
      ))}
    </div>
  );
}

export default function AIChatSection() {
  const [messages, setMessages] = useState<IChatMessage[]>(MOCK_CHAT_MESSAGES);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 自动滚动到底部
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  // 发送消息
  function handleSend(e?: FormEvent) {
    if (e) e.preventDefault();
    const text = inputValue.trim();
    if (!text) return;

    const userMsg: IChatMessage = {
      id: `msg-${Date.now()}`,
      sender: 'user',
      content: text,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInputValue('');
    setIsTyping(true);

    // 模拟AI回复
    setTimeout(() => {
      const reply =
        AI_REPLIES[text] ??
        '这是个好问题！让我想想... 🤔 建议你先从注意力测评开始，了解孩子的基础情况，然后我会为你推荐最适合的训练方案～';

      const aiMsg: IChatMessage = {
        id: `msg-${Date.now() + 1}`,
        sender: 'ai',
        content: reply,
        timestamp: Date.now(),
      };
      setMessages((prev) => [...prev, aiMsg]);
      setIsTyping(false);
    }, 1200 + Math.random() * 800);
  }

  // 快捷提问
  function handleQuickQuestion(q: string) {
    setInputValue(q);
    // 直接触发发送
    const userMsg: IChatMessage = {
      id: `msg-${Date.now()}`,
      sender: 'user',
      content: q,
      timestamp: Date.now(),
    };
    setMessages((prev) => [...prev, userMsg]);
    setIsTyping(true);

    setTimeout(() => {
      const reply =
        AI_REPLIES[q] ??
        '这是个好问题！让我想想... 🤔 建议你先从注意力测评开始，了解孩子的基础情况，然后我会为你推荐最适合的训练方案～';
      const aiMsg: IChatMessage = {
        id: `msg-${Date.now() + 1}`,
        sender: 'ai',
        content: reply,
        timestamp: Date.now(),
      };
      setMessages((prev) => [...prev, aiMsg]);
      setIsTyping(false);
    }, 1200 + Math.random() * 800);
  }

  return (
    <section className="w-full py-3 md:py-4">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <div className="grid grid-cols-1 lg:grid-cols-5 gap-4">
          {/* 左侧：AI数字人展示区 */}
          <div className="lg:col-span-2">
            <Card className="h-full border-2 border-primary/20 bg-gradient-to-b from-primary/5 to-background rounded-2xl overflow-hidden">
              <CardContent className="flex flex-col items-center justify-center p-4 md:p-6 h-full min-h-[280px]">
                {/* 数字人头像 */}
                <motion.div
                  className="relative"
                  animate={{ y: [0, -6, 0] }}
                  transition={{ duration: 3, repeat: Infinity, ease: 'easeInOut' }}
                >
                  <div className="size-28 md:size-36 rounded-full bg-gradient-to-br from-primary/20 via-accent/15 to-primary/10 p-1.5 shadow-lg shadow-primary/10">
                    <div className="size-full rounded-full bg-white/80 backdrop-blur-sm flex items-center justify-center overflow-hidden border-3 border-primary/20">
                      <Image
                        src={IMAGE_PATHS.elephantAvatar}
                        alt="小象AI助手"
                        className="size-full object-cover"
                      />
                    </div>
                  </div>
                  <motion.div
                    className="absolute -inset-2 rounded-full border-2 border-primary/20"
                    animate={{ scale: [1, 1.08, 1], opacity: [0.5, 0.2, 0.5] }}
                    transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' }}
                  />
                </motion.div>

                <div className="mt-3 text-center">
                  <h3 className="text-base font-bold text-foreground">小象AI助手</h3>
                  <p className="text-xs text-muted-foreground mt-0.5">专注力训练 · 智能问答</p>
                </div>

                <div className="mt-3 flex items-center gap-2">
                  <div className="size-2 rounded-full bg-green-400 animate-pulse" />
                  <span className="text-xs text-muted-foreground">在线中</span>
                  <VoiceWaveBars />
                </div>

                <p className="mt-4 text-center text-xs text-muted-foreground max-w-xs">
                  有任何关于注意力训练的问题，都可以问我哦～
                  <br />
                  点击下方快捷提问或直接输入～
                </p>
              </CardContent>
            </Card>
          </div>

          {/* 右侧：对话问答区 */}
          <div className="lg:col-span-3 flex flex-col">
            <Card className="flex-1 flex flex-col border-2 border-border/40 rounded-2xl overflow-hidden">
              <CardHeader className="pb-2 border-b border-border/30 bg-muted/30 py-2.5 px-4">
                <CardTitle className="text-base flex items-center gap-2">
                  <Sparkles className="size-4 text-accent" />
                  对话问答
                </CardTitle>
              </CardHeader>

              <CardContent className="flex-1 overflow-y-auto p-3 space-y-2.5 min-h-[200px] max-h-[280px]">
                {messages.map((msg) => (
                  <motion.div
                    key={msg.id}
                    initial={{ opacity: 0, y: 10, scale: 0.97 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
                    className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div
                      className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${
                        msg.sender === 'user'
                          ? 'bg-primary text-primary-foreground rounded-br-md'
                          : 'bg-muted text-foreground rounded-bl-md'
                      }`}
                    >
                      {msg.content}
                    </div>
                  </motion.div>
                ))}

                {/* AI正在输入 */}
                {isTyping && (
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex justify-start"
                  >
                    <div className="bg-muted text-foreground rounded-2xl rounded-bl-md px-4 py-3">
                      <div className="flex items-center gap-1.5">
                        <span className="size-2 rounded-full bg-muted-foreground/40 animate-bounce" style={{ animationDelay: '0ms' }} />
                        <span className="size-2 rounded-full bg-muted-foreground/40 animate-bounce" style={{ animationDelay: '150ms' }} />
                        <span className="size-2 rounded-full bg-muted-foreground/40 animate-bounce" style={{ animationDelay: '300ms' }} />
                      </div>
                    </div>
                  </motion.div>
                )}

                <div ref={messagesEndRef} />
              </CardContent>

              <div className="px-3 py-2 border-t border-border/30 bg-muted/20">
                <p className="text-[10px] text-muted-foreground mb-1.5">快捷提问：</p>
                <div className="flex flex-wrap gap-1.5">
                  {QUICK_QUESTIONS.map((q) => (
                    <Button
                      key={q}
                      variant="outline"
                      size="sm"
                      className="rounded-full text-[10px] h-7 bg-background hover:bg-primary/10 hover:text-primary hover:border-primary/30 transition-colors"
                      onClick={() => handleQuickQuestion(q)}
                    >
                      {q}
                    </Button>
                  ))}
                </div>
              </div>

              <form
                onSubmit={handleSend}
                className="flex items-center gap-2 px-3 py-2 border-t border-border/30 bg-background"
              >
                <Input
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  placeholder="输入你的问题..."
                  className="flex-1 rounded-xl bg-muted/50 border-border/40 focus-visible:ring-primary h-8 text-sm"
                  disabled={isTyping}
                />
                <Button
                  type="submit"
                  size="icon"
                  className="rounded-xl shrink-0 h-8 w-8"
                  disabled={!inputValue.trim() || isTyping}
                >
                  <Send className="size-3.5" />
                </Button>
              </form>
            </Card>
          </div>
        </div>
      </div>
    </section>
  );
}
