import { useState, memo } from 'react';
import { motion } from 'framer-motion';
import { Home, School, Apple, Heart, Activity, ChevronDown } from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import type { IGuideItem } from '@/types/attention';
import { MOCK_GUIDE_ITEMS } from '@/data/attention';

// ============================================================
// 图标映射：将 guide item 的 icon 字符串映射为 lucide-react 组件
// ============================================================
const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  Home,
  School,
  Apple,
  Heart,
  Activity,
};

// ============================================================
// 单条指南卡片
// ============================================================
function GuideCard({ item, index }: { item: IGuideItem; index: number }) {
  const [open, setOpen] = useState(false);
  const Icon = ICON_MAP[item.icon] || Home;

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5, delay: index * 0.08, ease: [0.16, 1, 0.3, 1] }}
    >
        <Collapsible open={open} onOpenChange={setOpen}>
        <Card className="overflow-hidden border-border/40 shadow-sm hover:shadow-md transition-shadow duration-300 h-full">
          <CollapsibleTrigger asChild>
            <button
              type="button"
              className="w-full text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-xl"
            >
              <CardHeader className="pb-2 pt-3 px-4">
                <div className="flex items-start gap-3">
                  <div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-primary/10">
                    <Icon className="size-5 text-primary" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <CardTitle className="text-sm font-semibold text-foreground">
                      {item.title}
                    </CardTitle>
                    <CardDescription className="mt-0.5 text-xs text-muted-foreground line-clamp-2">
                      {item.summary}
                    </CardDescription>
                  </div>
                  <ChevronDown
                    className={`size-4 shrink-0 text-muted-foreground transition-transform duration-200 mt-1 ${
                      open ? 'rotate-180' : ''
                    }`}
                  />
                </div>
              </CardHeader>
            </button>
          </CollapsibleTrigger>

          <CollapsibleContent>
            <CardContent className="pt-0 pb-4 px-4">
              <div className="ml-13 rounded-lg bg-muted/50 p-3">
                <p className="text-xs text-foreground/80 whitespace-pre-line leading-relaxed">
                  {item.content}
                </p>
              </div>
            </CardContent>
          </CollapsibleContent>
        </Card>
      </Collapsible>
    </motion.div>
  );
}

// ============================================================
// 干预指南列表 Section
// ============================================================
interface GuideListSectionProps {
  items?: IGuideItem[];
}

export default memo(function GuideListSection({ items = MOCK_GUIDE_ITEMS }: GuideListSectionProps) {
  return (
    <section className="w-full py-4">
      <div className="max-w-5xl mx-auto px-4 md:px-6">
        <div className="mb-4 text-center">
          <h2 className="text-xl md:text-2xl font-bold text-foreground">
            干预训练指南
          </h2>
          <p className="mt-1 text-sm text-muted-foreground">
            科学的干预方法，帮助孩子逐步提升注意力水平
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {items.map((item, index) => (
            <GuideCard key={item.id} item={item} index={index} />
          ))}
        </div>
      </div>
    </section>
  );
});
