// ============================================================
// 课堂行为观测量化分析
// ============================================================
function BehaviorObservationCards() {
  const observations: IBehaviorObservation[] = MOCK_BEHAVIOR_OBSERVATIONS;

  const trendIcon = (trend: IBehaviorObservation['trend']) => {
    switch (trend) {
      case 'up':
        return <TrendingUp className="size-4 text-success" />;
      case 'down':
        return <TrendingDown className="size-4 text-destructive" />;
      case 'stable':
        return <Minus className="size-4 text-muted-foreground" />;
    }
  };

  return (
    <Card className="rounded-2xl border-border/40 shadow-sm">
      <CardHeader>
        <CardTitle className="text-lg">课堂行为观测量化分析</CardTitle>
        <CardDescription>基于课堂录像的AI行为编码分析</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          {observations.map((obs) => (
            <div
              key={obs.id}
              className="flex flex-col items-center gap-2 rounded-xl border border-border/40 bg-muted/30 p-4"
            >
              <span className="text-xs text-muted-foreground">{obs.name}</span>
              <div className="flex items-baseline gap-1">
                <span className="text-3xl font-bold tabular-nums text-foreground">{obs.value}</span>
                <span className="text-sm text-muted-foreground">{obs.unit}</span>
              </div>
              <div className="flex items-center gap-1 text-xs">
                {trendIcon(obs.trend)}
                <span className={obs.trend === 'up' ? 'text-success' : obs.trend === 'down' ? 'text-destructive' : 'text-muted-foreground'}>
                  {obs.trendLabel}
                </span>
              </div>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

// ============================================================
// 阶段专业成长分析报告
// ============================================================
function GrowthReportCard() {
  const baseline = MOCK_TEST_RECORDS.find((r) => r.isBaseline);
  const followUp = MOCK_TEST_RECORDS.find((r) => !r.isBaseline);

  if (!baseline || !followUp) return null;

  const improvements = [
    { label: '持续性注意力', before: baseline.sustainedAttention, after: followUp.sustainedAttention },
    { label: '选择性注意力', before: baseline.selectiveAttention, after: followUp.selectiveAttention },
    { label: '分配注意力', before: baseline.dividedAttention, after: followUp.dividedAttention },
    { label: '抑制控制', before: baseline.inhibitoryControl, after: followUp.inhibitoryControl },
  ];

  return (
    <Card className="rounded-2xl border-border/40 shadow-sm">
      <CardHeader>
        <CardTitle className="text-lg">阶段专业成长分析报告</CardTitle>
        <CardDescription>8周训练前后对比</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {improvements.map((item) => {
            const gain = item.after - item.before;
            const pct = Math.round((gain / item.before) * 100);
            return (
              <div key={item.label} className="flex items-center gap-4">
                <span className="w-28 shrink-0 text-sm font-medium">{item.label}</span>
                <div className="flex-1 flex items-center gap-2 min-w-0">
                  <span className="text-xs tabular-nums text-muted-foreground w-8 text-right">{item.before}</span>
                  <div className="flex-1 h-3 rounded-full bg-muted overflow-hidden relative">
                    <div
                      className="absolute inset-y-0 left-0 rounded-full bg-gradient-to-r from-chart-1 to-chart-2"
                      style={{ width: `${Math.max(item.after, 4)}%` }}
                    />
                  </div>
                  <span className="text-xs tabular-nums font-semibold w-8">{item.after}</span>
                  <span className="text-xs tabular-nums text-success font-medium w-14 text-right">
                    +{gain} (+{pct}%)
                  </span>
                </div>
              </div>
            );
          })}
        </div>
        <div className="mt-6 rounded-xl border border-border/40 bg-muted/20 p-4">
          <p className="text-sm text-muted-foreground leading-relaxed">
            经过8周的系统训练，学员在四项核心注意力指标上均取得显著进步。其中<strong className="text-foreground">持续性注意力提升最为突出（+23分，+44%）</strong>，
            表明训练方案对注意力的基础维持能力改善效果最佳。选择性注意力和抑制控制也有大幅提升，
            分配注意力作为较复杂的认知功能，进步幅度相对较小，建议在下一阶段训练中增加多任务并行训练的比重。
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

// ============================================================
// 分层个性化长期训练方案
// ============================================================
