// ============================================================
// 主 Section 组件
// ============================================================
export default function RecordsTableSection() {
  const stagger = useMemo(
    () => ({
      initial: { opacity: 0, y: 20 },
      whileInView: { opacity: 1, y: 0 },
      viewport: { once: true, margin: '-60px' },
      transition: { duration: 0.5, ease: [0.16, 1, 0.3, 1] as const },
    }),
    [],
  );

  return (
    <div className="space-y-6">
      <motion.div {...stagger}>
        <TestRecordsTable />
      </motion.div>

      <motion.div {...stagger} transition={{ ...stagger.transition, delay: 0.05 }}>
        <TrainLogTable />
      </motion.div>

      <motion.div {...stagger} transition={{ ...stagger.transition, delay: 0.1 }}>
        <BehaviorObservationCards />
      </motion.div>

      <motion.div {...stagger} transition={{ ...stagger.transition, delay: 0.15 }}>
        <GrowthReportCard />
      </motion.div>

      <motion.div {...stagger} transition={{ ...stagger.transition, delay: 0.2 }}>
        <LongTermPlanCard />
      </motion.div>
    </div>
  );
}
