import { NavLink, useLocation } from 'react-router-dom';
import { BookOpen, ListChecks, Video, Gamepad2, Home } from 'lucide-react';

const NAV_ITEMS = [
  { path: '/', label: '首页', icon: Home },
  { path: '/home-family', label: '小象百科', icon: BookOpen },
  { path: '/guide', label: '干预指南', icon: ListChecks },
  { path: '/science', label: '科普视频', icon: Video },
  { path: '/train-detail', label: '趣味互动', icon: Gamepad2 },
] as const;

export default function AppSidebar() {
  const { pathname } = useLocation();

  return (
    <aside className="fixed left-0 top-0 z-40 flex h-screen w-[100px] flex-col items-center border-r border-border/40 bg-white/70 backdrop-blur-md pt-20">
      <nav className="flex flex-col items-center gap-3 w-full px-2">
        {NAV_ITEMS.map((item) => {
          const Icon = item.icon;
          const isActive = pathname === item.path || pathname.startsWith(`${item.path}/`);

          return (
            <NavLink
              key={item.path}
              to={item.path}
              end={item.path === '/'}
              className={({ isActive: linkActive }) =>
                `flex flex-col items-center justify-center gap-1 w-full rounded-xl py-3 px-1 text-center transition-all duration-200 ${
                  linkActive
                    ? 'bg-primary/10 text-primary'
                    : 'text-muted-foreground hover:bg-muted/60 hover:text-foreground'
                }`
              }
            >
              <Icon className="size-5 shrink-0" />
              <span className="text-[11px] leading-tight font-medium">{item.label}</span>
            </NavLink>
          );
        })}
      </nav>
    </aside>
  );
}
